const serviceName = $json.service_name || 'my-service';
const price = $json.price_usd || '0.001';
const wallet = $json.wallet_address || '0xYourWallet';

return [{ json: { service_name: serviceName, price_usd: price, wallet_address: wallet } }];

const fs = require('fs');
const path = require('path');

const { service_name, price_usd, wallet_address } = $json;

// Generate server.js
const serverCode = `// ${service_name} x402 API
// Auto-generated by n8n

const http = require('http');
const https = require('https');
const crypto = require('crypto');
const url = require('url');

const PORT = process.env.PORT || 3000;
const NETWORK = 'base';
const PRICE_USD = '${price_usd}';
const PAY_TO = '${wallet_address}';

function buildPaymentRequirements(path, method, price = PRICE_USD, description) {
  return {
    x402Version: 1,
    accepts: [{
      scheme: 'exact',
      network: NETWORK,
      maxAmountRequired: price,
      resource: \`https://your-api.com\${path}\`,
      description: description || \`Service — $${price} USDC per call\`,
      mimeType: 'application/json',
      payTo: PAY_TO,
      extra: { name: 'USDC', icon: 'https://raw.githubusercontent.com/messari/token-icons/master/raw-USDC.svg' }
    }]
  };
}

function encodePaymentHeader(obj) {
  return Buffer.from(JSON.stringify(obj)).toString('base64');
}

function decodePaymentHeader(str) {
  try { return JSON.parse(Buffer.from(str, 'base64').toString()); } catch { return null; }
}

function getPaymentHeader(req) {
  return req.headers['payment-signature'] || req.headers['x-payment'];
}

function checkPayment(req, res, path, method, price, description) {
  const paymentHeader = getPaymentHeader(req);
  if (!paymentHeader) {
    const reqs = buildPaymentRequirements(path, method, price);
    sendJSON(res, 402, { error: 'Payment required', paymentRequired: reqs }, {
      'X-PAYMENT-REQUIRED': encodePaymentHeader(reqs)
    });
    return null;
  }
  const payload = decodePaymentHeader(paymentHeader);
  if (!payload) { sendJSON(res, 400, { error: 'Invalid payment header' }); return null; }
  // Demo mode
  return true;
}

function sendJSON(res, status, obj, headers = {}) {
  const body = JSON.stringify(obj);
  res.writeHead(status, { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body), ...headers });
  res.end(body);
}

// YOUR SERVICE LOGIC HERE
function yourService(input) {
  return { result: \`Processed: \${input}\` };
}

const routes = {
  'POST /api/${service_name}': async (req, res) => {
    const payment = checkPayment(req, res, '/api/${service_name}', 'POST', PRICE_USD, \`${service_name} — $${PRICE_USD} USDC per call\`);
    if (!payment) return;
    try {
      const body = JSON.parse(req._rawBody || '{}');
      const result = yourService(body.input);
      sendJSON(res, 200, result);
    } catch (err) {
      sendJSON(res, 500, { error: 'Internal error' });
    }
  }
};

const server = http.createServer(async (req, res) => {
  const corsHeaders = { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Methods': 'POST, GET, OPTIONS', 'Access-Control-Allow-Headers': 'Content-Type, X-PAYMENT' };
  if (req.method === 'OPTIONS') { res.writeHead(204, corsHeaders); return res.end(); }
  const parsed = url.parse(req.url);
  const routeKey = \`\${req.method} \${parsed.pathname}\`;
  const handler = routes[routeKey];
  if (!handler) return sendJSON(res, 404, { error: 'Not found' }, corsHeaders);
  if (req.method === 'POST') {
    req._rawBody = await new Promise((resolve, reject) => {
      const chunks = [];
      req.on('data', c => chunks.push(c));
      req.on('end', () => resolve(Buffer.concat(chunks).toString()));
      req.on('error', reject);
    });
  }
  const origWriteHead = res.writeHead.bind(res);
  res.writeHead = (status, headers = {}) => origWriteHead(status, { ...headers, ...corsHeaders });
  try { await handler(req, res); } catch (err) { sendJSON(res, 500, { error: 'Internal server error' }, corsHeaders); }
});

server.listen(PORT, () => console.log(\`🔮 ${service_name} API on port \${PORT}\`));
`;

// Write to file
const outputDir = '/tmp/x402-generated';
if (!fs.existsSync(outputDir)) fs.mkdirSync(outputDir, { recursive: true });
fs.writeFileSync(path.join(outputDir, 'server.js'), serverCode);

return [{ json: { service_name, price_usd, wallet_address, server_path: path.join(outputDir, 'server.js'), message: 'Server code generated. Run: node server.js' } }];

const { service_name, price_usd, wallet_address, server_path } = $json;

return [{ json: {
  service_name,
  price_usd,
  wallet_address,
  server_path,
  deploy_commands: [
    `cd /tmp/x402-generated`,
    `nohup node server.js > server.log 2>&1 &`,
